const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='countschedula-pilot-v1',names=['Emma Wilson','Sarah Chen','Olivia Brooks','Rachel Morgan','Mia Patel','Hannah Davis','Claire Bennett','Ava Thompson'];
const depts=[{id:'willow',name:'Jones Team · Labor & Delivery',org:'Jones Team'},{id:'river',name:'Boehm Team · Birth Center',org:'Boehm Team'}];
let state,view='Schedule',dept='willow',cursor=new Date(2026,10,1),mode='Month',selectedOrgs=['willow'],filter='',history=[];
function seed(){return {providers:names.map((name,i)=>({id:'p'+i,name,role:'CNM',target:i===7?6:10,max:14,nights:true,affiliations:i<3?['willow','river']:['willow']})),assignments:[],requests:[{id:'r1',provider:'p2',start:'2026-11-12',end:'2026-11-14',status:'Pending',reason:'Family trip'},{id:'r2',provider:'p4',start:'2026-11-23',end:'2026-11-25',status:'Approved',reason:'Personal time'}],rules:{rest:12,consecutive:3,dayCoverage:1,nightCoverage:1},periods:{},audit:[]}}
try{state=JSON.parse(localStorage.getItem(KEY))||seed()}catch{state=seed()}

function defaultShiftTypes(rules={}){return [
{id:'day',name:'Day',start:'07:00',end:'19:00',color:'#6b9b69',coverage:rules.dayCoverage??1,night:false,active:true},
{id:'night',name:'Night',start:'19:00',end:'07:00',color:'#8a79b2',coverage:rules.nightCoverage??1,night:true,active:true},
{id:'clinic-am',name:'Clinic AM',start:'08:00',end:'12:00',color:'#5c9db0',coverage:0,night:false,active:true},
{id:'clinic-pm',name:'Clinic PM',start:'13:00',end:'17:00',color:'#b28e56',coverage:0,night:false,active:true},
{id:'triage',name:'Triage',start:'09:00',end:'21:00',color:'#b47783',coverage:0,night:false,active:true},
{id:'flex',name:'Flex',start:'11:00',end:'19:00',color:'#728caf',coverage:0,night:false,active:true}]}
function migrate(data){if(!data.shiftTypes)data.shiftTypes=defaultShiftTypes(data.rules);for(let event of data.audit||[]){if(typeof event.text==='string')event.text=event.text.replace(/Willow Women[’']s Health|Willow/g,'Jones Team').replace(/Riverside Hospital|Riverside/g,'Boehm Team')}return data}
state=migrate(state);
function shiftType(id){return state.shiftTypes.find(t=>t.id===id)}
function activeTypes(){return state.shiftTypes.filter(t=>t.active)}
function shiftName(id){return shiftType(id)?.name||id}
function minutes(t){let [h,m]=t.split(':').map(Number);return h*60+m}
function shiftHours(id){let t=shiftType(id);if(!t)return 0;return ((minutes(t.end)-minutes(t.start)+1440)%1440||1440)/60}
function clock(t){let [h,m]=t.split(':').map(Number);return (h%12||12)+(m?':'+String(m).padStart(2,'0'):'')+(h<12?'a':'p')}
function shiftRange(t){return clock(t.start)+'–'+clock(t.end)}
function shiftOptions(selected){return state.shiftTypes.filter(t=>t.active||t.id===selected).map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(t.name)} · ${shiftRange(t)}${t.active?'':' (inactive)'}</option>`).join('')}

function iso(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function date(s){return new Date(s+'T00:00:00')}function plus(s,n){let d=date(s);d.setDate(d.getDate()+n);return iso(d)}function monthKey(d=cursor){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}function periodKey(){return dept+':'+monthKey()}function locked(){return state.periods[periodKey()]?.status==='Published'}
function persist(){localStorage.setItem(KEY,JSON.stringify(state))}function audit(text){state.audit.unshift({text,time:new Date().toISOString()});state.audit=state.audit.slice(0,300)}function commit(text){audit(text);persist();render()}function checkpoint(){history.push(JSON.stringify(state));if(history.length>20)history.shift()}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function provider(id){return state.providers.find(p=>p.id===id)}function initials(p){return p.name.split(' ').map(s=>s[0]).slice(0,2).join('')}function relevant(department=dept){return state.assignments.filter(a=>a.dept===department&&a.date.startsWith(monthKey()))}function daysInMonth(){return new Date(cursor.getFullYear(),cursor.getMonth()+1,0).getDate()}function totalSlots(){return daysInMonth()*activeTypes().reduce((n,t)=>n+t.coverage,0)}function deptName(id=dept){return depts.find(d=>d.id===id)?.name||id}function approved(p,day){return state.requests.some(r=>r.provider===p&&r.status==='Approved'&&day>=r.start&&day<=r.end)}
function interval(a){let t=shiftType(a.shift);if(!t)return [NaN,NaN];let start=date(a.date);start.setHours(...t.start.split(':').map(Number),0,0);let end=date(a.date);end.setHours(...t.end.split(':').map(Number),0,0);if(end<=start)end.setDate(end.getDate()+1);return [+start,+end]}
function violations(a,list=state.assignments){let errors=[],p=provider(a.provider);if(!p)return ['Provider does not exist'];if(!p.affiliations.includes(a.dept))errors.push('Provider is not affiliated with this department');if(!shiftType(a.shift))return ['Unknown shift type'];if(shiftType(a.shift).night&&!p.nights)errors.push('Provider is unavailable for nights');const [s,e]=interval(a);for(let r of state.requests.filter(r=>r.provider===p.id&&r.status==='Approved')){if(s<date(plus(r.end,1)).getTime()&&e>date(r.start).getTime())errors.push('Approved PTO overlaps this shift')}
const others=list.filter(b=>b.id!==a.id&&b.provider===a.provider);for(let b of others){let [bs,be]=interval(b);if(s<be&&e>bs)errors.push('Overlapping assignment · '+deptName(b.dept));else{let gap=s>=be?(s-be)/3600000:(bs-e)/3600000;if(gap<state.rules.rest)errors.push('Minimum '+state.rules.rest+'h rest not met · '+b.date)}}
let n=others.filter(b=>b.date.slice(0,7)===a.date.slice(0,7)).length;if(n>=p.max)errors.push('Monthly maximum of '+p.max+' shifts exceeded');let dates=new Set([...others.map(b=>b.date),a.date]),streak=1;for(let i=1;dates.has(plus(a.date,-i));i++)streak++;for(let i=1;dates.has(plus(a.date,i));i++)streak++;if(streak>state.rules.consecutive)errors.push('Maximum '+state.rules.consecutive+' consecutive workdays exceeded');return [...new Set(errors)]}
function validateAll(department=dept){return relevant(department).flatMap(a=>violations(a).map(error=>({a,error})))}function coverageMissing(department=dept){let gaps=[];for(let n=1;n<=daysInMonth();n++){let day=iso(new Date(cursor.getFullYear(),cursor.getMonth(),n));for(let t of activeTypes()){let shift=t.id,need=t.coverage,have=state.assignments.filter(a=>a.dept===department&&a.date===day&&a.shift===shift).length;for(let i=have;i<need;i++)gaps.push({date:day,shift})}}return gaps}
function canEdit(dateValue,department=dept){if(state.periods[department+':'+dateValue.slice(0,7)]?.status==='Published'){toast('This schedule is published. Reopen it as a draft to edit.');return false}return true}
function addAssignment(a){if(!canEdit(a.date,a.dept))return false;let errs=violations(a);if(errs.length){toast(errs[0]);return false}checkpoint();state.assignments.push(a);commit('Assigned '+provider(a.provider).name+' · '+a.date+' '+a.shift);return true}
function closeSidebar(){document.body.classList.remove('sidebar-open');document.querySelector('#menuToggle').setAttribute('aria-expanded','false')}
function toggleSidebar(){const open=document.body.classList.toggle('sidebar-open');document.querySelector('#menuToggle').setAttribute('aria-expanded',String(open))}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('sidebar-open')){closeSidebar();document.querySelector('#menuToggle').focus()}});
function navigate(v){view=v;closeSidebar();render()}const pages=[['▦','Schedule'],['♧','Providers'],['◷','Requests'],['◫','Shift types'],['☷','Rules & coverage'],['▤','Reports'],['↺','Activity'],['⚙','Settings']];
function render(){let pending=state.requests.filter(r=>r.status==='Pending').length;$('#nav').innerHTML=pages.map(([icon,name])=>`<button class="${view===name?'active':''}" onclick="navigate('${name}')"><span>${icon}</span>${name}${name==='Requests'&&pending?`<span class="badge">${pending}</span>`:''}</button>`).join('');$('#breadcrumb').innerHTML='Workspace <b>/</b> '+view;$('#main').innerHTML=({Schedule:schedule,Providers:providersPage,Requests:requestsPage,'Shift types':shiftTypesPage,'Rules & coverage':rulesPage,Reports:reportsPage,Activity:activityPage,Settings:settingsPage}[view])();bindDnD()}
function title(name,sub,actions=''){return `<div class="titlebar"><div><h1>${name}</h1><p class="sub">${sub}</p></div><div class="actions">${actions}</div></div>`}function deptSelect(){return `<select aria-label="Department" onchange="dept=this.value;render()">${depts.map(d=>`<option value="${d.id}" ${d.id===dept?'selected':''}>${d.name}</option>`).join('')}</select>`}
function stats(){let departments=view==='Schedule'?displayDepartments():depts.filter(d=>d.id===dept),slots=totalSlots()*departments.length,gaps=departments.flatMap(d=>coverageMissing(d.id)).length,issues=departments.flatMap(d=>validateAll(d.id)).length;return `<div class="stats"><div class="stat"><div class="label">Shift coverage <span>◉</span></div><strong>${Math.round((slots?(slots-gaps)/slots*100:100))}<span style="font-size:15px">%</span></strong><small>${slots-gaps} of ${slots} covered</small><div class="bar"><i style="width:${(slots?(slots-gaps)/slots*100:100)}%"></i></div></div><div class="stat"><div class="label">Open shifts <span>☀</span></div><strong>${gaps}</strong><small>need a little attention</small></div><div class="stat"><div class="label">Active providers <span>♧</span></div><strong>${state.providers.filter(p=>departments.some(d=>p.affiliations.includes(d.id))).length}</strong><small>in selected organizations</small></div><div class="stat"><div class="label">Rule conflicts <span>♧</span></div><strong style="color:${issues?'#aa7549':'#518065'}">${issues}</strong><small>${issues?'review before publishing':'looking good'}</small></div></div>`}
function schedule(){let mon=cursor.toLocaleString('en-US',{month:'long',year:'numeric'}),gaps=displayDepartments().flatMap(d=>coverageMissing(d.id)),issues=displayDepartments().flatMap(d=>validateAll(d.id));return title('A schedule everyone can breathe with.','Your team, in balance. Your coverage, taken care of.',`<button onclick="exportCSV()">↗ Export</button><button onclick="generateDialog()" ${locked()?'disabled':''}>✧ Generate ${esc(organizationFor(dept).short)}</button><button class="primary" onclick="publishDialog()">${locked()?'✓ Published':'Publish'} ${esc(organizationFor(dept).short)} ↗</button>`)+stats()+`<div class="toolbar"><div class="filters">${organizationPicker()}<select aria-label="Filter provider" onchange="filter=this.value;render()"><option value="">All providers</option>${state.providers.map(p=>`<option value="${p.id}" ${filter===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="segmented">${['Month','Week'].map(v=>`<button class="${mode===v?'selected':''}" onclick="mode='${v}';render()">${v}</button>`).join('')}</div></div><div class="schedule-context"><div class="org-key">${displayOrganizations().map(o=>`<span><i class="dot" style="background:${o.color}"></i>${esc(o.name)}</span>`).join('')}</div><label class="manage-target">Edit / generate / publish for ${deptSelect()}</label></div><div class="calendarwrap"><div class="calhead"><div><h2>${mon}</h2><span class="pill ${locked()?'green':''}">${esc(organizationFor(dept).short)} · ${locked()?'Published':'Draft'}</span></div><div><button class="icon" aria-label="Previous period" onclick="changePeriod(-1)">‹</button><button onclick="cursor=new Date();cursor.setDate(1);render()" style="font-size:10px;padding:5px 10px">Today</button><button class="icon" aria-label="Next period" onclick="changePeriod(1)">›</button><small>${mode==='Month'?'Monthly overview':'Week of '+iso(cursor)}</small></div></div>${locked()?'<div class="locknote">✓ The editing target’s published schedule is locked. Other organizations retain their own edit status. <a href="#" onclick="reopen();return false">Reopen draft</a> to make changes.</div>':''}<div class="calendar ${mode==='Week'?'week':''}">${calendarCells()}</div><div class="legend"><div>${activeTypes().map(t=>`<span><i class="dot" style="background:${t.color}"></i>${esc(t.name)} · ${shiftRange(t)}</span>`).join('')}</div><span>Drag to move · Click to edit</span></div></div><div class="below"><div class="panel"><div class="panelhead"><div><h3>Your team, ready to go</h3><p style="margin:4px 0 0">Drag a provider onto a date to add a shift.</p></div><button onclick="navigate('Providers')">Manage team ↗</button></div>${state.providers.filter(p=>displayDepartments().some(d=>p.affiliations.includes(d.id))).map(p=>`<div draggable="true" class="providerchip" data-provider="${p.id}"><span class="initials">${initials(p)}</span>${esc(p.name)}</div>`).join('')}<p>Rest and workload checks include both organizations.</p></div><div class="panel"><div class="panelhead"><h3>A little peace of mind</h3><button onclick="navigate('Reports')">View details ↗</button></div><div class="notice ${!gaps.length&&!issues.length?'good':''}">${issues.length?'⚠ '+issues.length+' rule conflicts require review.':gaps.length?'☀ '+gaps.length+' open shifts left to fill. Generate a draft or drag in a provider.':'✓ All required shifts are covered. No rule conflicts detected.'}</div><p>${state.requests.filter(r=>r.status==='Pending').length} time-off requests awaiting review · <a href="#" onclick="navigate('Requests');return false">Review requests</a></p></div></div>`}
function calendarCells(){let start=new Date(cursor.getFullYear(),cursor.getMonth(),1);if(mode==='Week')start=new Date(cursor);start.setDate(start.getDate()-start.getDay());let html=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="dow">${d}</div>`).join(''),length=mode==='Week'?7:Math.ceil((new Date(cursor.getFullYear(),cursor.getMonth(),1).getDay()+daysInMonth())/7)*7;for(let i=0;i<length;i++){let d=new Date(start);d.setDate(d.getDate()+i);let day=iso(d),out=d.getMonth()!==cursor.getMonth();html+=`<div class="day ${out?'out':''} ${[0,6].includes(d.getDay())?'weekend':''}" data-date="${day}"><div class="date"><button class="add" aria-label="Add assignment ${day}" onclick="assignmentDialog(null,'${day}')">+</button><span class="${day===iso(new Date())?'today':''}">${d.getDate()}</span></div>${displayDepartments().map(department=>{let org=organizationFor(department.id),assign=state.assignments.filter(a=>a.dept===department.id&&a.date===day&&(!filter||a.provider===filter)).sort((a,b)=>minutes(shiftType(a.shift).start)-minutes(shiftType(b.shift).start));return `<section class="org-lane dropzone" data-date="${day}" data-dept="${department.id}" style="--org-color:${org.color}"><div class="org-lane-title"><span class="org-dot"></span>${esc(org.short)}<span class="lane-lock">${isPublished(department.id,day)?'Locked':''}</span></div>${assign.map(a=>`<div role="button" tabindex="0" aria-label="Edit ${esc(provider(a.provider)?.name)} ${esc(shiftName(a.shift))} ${day} ${esc(org.name)}" draggable="${!isPublished(a.dept,a.date)}" data-assignment="${a.id}" class="assignment" style="border-color:${shiftType(a.shift)?.color}66;background:${shiftType(a.shift)?.color}18;color:${shiftType(a.shift)?.color}" onclick="assignmentDialog('${a.id}')" onkeydown="if(event.key==='Enter')assignmentDialog('${a.id}')"><span class="shifticon">${shiftType(a.shift)?.night?'☾':'☀'}</span><span>${esc(provider(a.provider)?.name||'Unknown')}<b class="shift-caption">${esc(shiftName(a.shift))} · ${shiftRange(shiftType(a.shift))}</b><b class="assignment-org">${esc(org.short)}</b></span></div>`).join('')}${!out&&!filter?activeTypes().map(t=>{let have=state.assignments.filter(a=>a.dept===department.id&&a.date===day&&a.shift===t.id).length;return Array.from({length:Math.max(0,t.coverage-have)},()=>`<div class="assignment open dropzone" role="button" tabindex="0" aria-label="Open ${esc(t.name)} ${esc(org.name)} ${day}" data-date="${day}" data-dept="${department.id}" data-shift="${t.id}" onclick="assignmentDialog(null,'${day}','${t.id}',null,'${department.id}')" onkeydown="if(event.key==='Enter')assignmentDialog(null,'${day}','${t.id}',null,'${department.id}')"><span>${t.night?'☾':'☀'}</span> Open ${esc(t.name)}<small>+</small></div>`).join('')}).join(''):''}</section>`}).join('')}</div>`}return html}
function changePeriod(n){if(mode==='Week')cursor.setDate(cursor.getDate()+n*7);else cursor=new Date(cursor.getFullYear(),cursor.getMonth()+n,1);render()}
function bindDnD(){document.querySelectorAll('[data-assignment],[data-provider]').forEach(el=>{el.addEventListener('dragstart',e=>{if(el.dataset.assignment){let a=state.assignments.find(a=>a.id===el.dataset.assignment);if(a&&isPublished(a.dept,a.date)){e.preventDefault();return}}e.dataTransfer.setData('text/plain',JSON.stringify(el.dataset.assignment?{id:el.dataset.assignment}:{provider:el.dataset.provider}));e.dataTransfer.effectAllowed='move'})});document.querySelectorAll('.day,.dropzone').forEach(el=>{el.addEventListener('dragover',e=>{e.preventDefault();e.stopPropagation();el.classList.add('dragover')});el.addEventListener('dragleave',()=>el.classList.remove('dragover'));el.addEventListener('drop',e=>{e.preventDefault();e.stopPropagation();document.querySelectorAll('.dragover').forEach(x=>x.classList.remove('dragover'));let payload;try{payload=JSON.parse(e.dataTransfer.getData('text/plain'))}catch{return}if(payload.provider){let target=el.dataset.dept||dept;if(!canEdit(el.dataset.date,target))return;assignmentDialog(null,el.dataset.date,el.dataset.shift||'day',payload.provider,target);return}let old=state.assignments.find(a=>a.id===payload.id);if(!old||!canEdit(old.date,old.dept))return;let updated={...old,date:el.dataset.date,shift:el.dataset.shift||old.shift,dept:el.dataset.dept||old.dept};if(!canEdit(updated.date,updated.dept))return;let errs=violations(updated);if(errs.length){toast('Move blocked: '+errs[0]);return}checkpoint();Object.assign(old,updated);commit('Moved '+provider(old.provider).name+' to '+old.date+' '+old.shift);toast('Assignment moved · Undo is available in Activity')})})}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal()}function closeModal(){$('#modal').close()}function id(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}function assignmentDialog(aid,day,shift='day',pid,targetDept=dept){let a=state.assignments.find(x=>x.id===aid),d=a?.date||day||iso(cursor);targetDept=a?.dept||targetDept;modal(`<h2>${a?'Edit assignment':'Add a shift'}</h2><p>A good schedule starts with the right fit.</p><form onsubmit="saveAssignment(event,'${aid||''}')"><div class="formgrid"><label class="full">Organization / department<select name="department" required onchange="updateAssignmentProviders(this.value)">${depts.map(x=>`<option value="${x.id}" ${x.id===targetDept?'selected':''}>${esc(x.org)} · ${esc(x.name)}</option>`).join('')}</select></label><label class="full">Provider<select name="provider" required>${state.providers.filter(p=>p.affiliations.includes(targetDept)).map(p=>`<option value="${p.id}" ${p.id===(a?.provider||pid)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Date<input name="date" type="date" value="${d}" required></label><label>Shift type<select name="shift" required>${shiftOptions(a?.shift||shift)}</select></label><label class="full">Notes<textarea name="note" rows="2" maxlength="500">${esc(a?.note||'')}</textarea></label></div><div id="formerror" class="danger" role="alert"></div><div class="modalactions">${a?`<button type="button" class="danger" onclick="deleteAssignment('${a.id}')">Remove shift</button>`:''}<button type="button" onclick="closeModal()">Cancel</button><button class="primary" ${isPublished(targetDept,d)?'disabled':''}>Save assignment</button></div></form>`)}
function saveAssignment(e,aid){e.preventDefault();let f=new FormData(e.target),old=state.assignments.find(a=>a.id===aid),a={id:aid||id(),provider:f.get('provider'),date:f.get('date'),shift:f.get('shift'),dept:f.get('department')||old?.dept||dept,note:f.get('note')};if(old&&!canEdit(old.date,old.dept))return;if(!canEdit(a.date,a.dept))return;let errors=violations(a);if(errors.length){$('#formerror').textContent=errors.join(' · ');return}checkpoint();if(old)Object.assign(old,a);else state.assignments.push(a);closeModal();commit('Saved '+provider(a.provider).name+' · '+a.date+' '+a.shift);toast('Assignment saved')}
function deleteAssignment(aid){let a=state.assignments.find(x=>x.id===aid);if(!canEdit(a.date,a.dept))return;checkpoint();state.assignments=state.assignments.filter(x=>x.id!==aid);closeModal();commit('Removed assignment · '+a.date);toast('Shift removed')}
function generateDialog(){if(locked())return;modal(`<h2>Make room for a better month.</h2><p>Fill open ${cursor.toLocaleString('en-US',{month:'long'})} shifts for ${esc(deptName())}. Existing assignments stay in place. The generator checks approved PTO, affiliations, global rest, consecutive workdays, and monthly maximums.</p><div class="notice good">Assignments are chosen to balance workload and nights. Targets guide selection; maximums are enforced. Unfillable shifts stay open.</div><div class="modalactions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="generate()">✧ Generate draft</button></div>`)}
function generate(silent=false){if(locked())return;checkpoint();let added=0;for(let gap of coverageMissing()){let candidates=state.providers.filter(p=>p.affiliations.includes(dept)).map(p=>{let all=state.assignments.filter(a=>a.provider===p.id&&a.date.startsWith(monthKey())),nights=all.filter(a=>shiftType(a.shift)?.night).length,weekends=all.filter(a=>[0,6].includes(date(a.date).getDay())).length;return {p,score:all.length/Math.max(p.target,1)*10+(shiftType(gap.shift)?.night?nights*.7:0)+([0,6].includes(date(gap.date).getDay())?weekends*.7:0)}}).sort((a,b)=>a.score-b.score||a.p.name.localeCompare(b.p.name));for(let {p} of candidates){let a={...gap,id:id(),provider:p.id,dept};if(!violations(a).length){state.assignments.push(a);added++;break}}}if($('#modal').open)closeModal();commit('Generated '+added+' assignments · '+deptName()+' · '+monthKey());if(!silent)toast(added+' shifts filled · '+coverageMissing().length+' remain open')}
function publishDialog(){if(locked()){reopen();return}let gaps=coverageMissing(),issues=validateAll();modal(`<h2>${gaps.length||issues.length?'A few things need attention.':'Ready for the team.'}</h2><p>${gaps.length} open shifts · ${issues.length} rule conflicts. Publishing locks this department’s schedule for ${monthKey()}.</p><div class="notice ${gaps.length||issues.length?'':'good'}">${gaps.length||issues.length?'Resolve coverage gaps and rule conflicts before publishing.':'✓ Coverage and configured scheduling rules passed validation.'}</div><div class="modalactions"><button onclick="closeModal()">Back to schedule</button><button class="primary" ${gaps.length||issues.length?'disabled':''} onclick="publish()">Publish schedule</button></div>`)}function publish(){if(coverageMissing().length||validateAll().length)return;checkpoint();state.periods[periodKey()]={status:'Published',at:new Date().toISOString(),snapshot:JSON.parse(JSON.stringify(relevant()))};closeModal();commit('Published '+deptName()+' · '+monthKey());toast('Schedule published and locked')}
function reopen(){modal(`<h2>Reopen this schedule?</h2><p>The published snapshot remains in this browser’s data. Reopening allows changes; publish again after review.</p><div class="modalactions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="checkpoint();state.periods[periodKey()].status='Draft';closeModal();commit('Reopened schedule · '+monthKey())">Reopen draft</button></div>`)}
function providersPage(){return title('People first. Always.','One provider profile. Every affiliation. A complete view of their commitments.',`<button class="primary" onclick="providerDialog()">+ Add provider</button>`)+`<div class="toolbar">${deptSelect()}<input class="search" placeholder="Search providers…" aria-label="Search providers" oninput="filterProviders(this.value)"></div><div class="tablewrap"><table><thead><tr><th>Provider</th><th>Role</th><th>Affiliations</th><th>Monthly target / max</th><th>Night shifts</th><th></th></tr></thead><tbody>${state.providers.map(p=>`<tr data-name="${esc(p.name.toLowerCase())}"><td><div class="namecell"><span class="avatar">${initials(p)}</span><strong>${esc(p.name)}</strong></div></td><td>${esc(p.role)}</td><td>${p.affiliations.map(d=>esc(deptName(d))).join('<br>')}</td><td>${p.target} / ${p.max}</td><td>${p.nights?'Available':'Days only'}</td><td><button onclick="providerDialog('${p.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div><div class="notice good" style="margin-top:20px">Shared providers use a single profile. All assignments across both organizations count toward rest and monthly maximum checks.</div>`}
function filterProviders(v){document.querySelectorAll('tr[data-name]').forEach(tr=>tr.hidden=!tr.dataset.name.includes(v.toLowerCase()))}
function providerDialog(pid){let p=provider(pid);modal(`<h2>${p?'Edit provider':'Meet your newest teammate.'}</h2><p>Affiliations define where this provider can be assigned.</p><form onsubmit="saveProvider(event,'${pid||''}')"><div class="formgrid"><label class="full">Full name<input name="name" value="${esc(p?.name||'')}" required maxlength="60"></label><label>Role<input name="role" value="${esc(p?.role||'CNM')}" required maxlength="30"></label><label>Night availability<select name="nights"><option value="yes">Available for nights</option><option value="no" ${p&&!p.nights?'selected':''}>Day shifts only</option></select></label><label>Monthly target<input type="number" name="target" value="${p?.target??10}" min="0" max="62" required></label><label>Monthly maximum<input type="number" name="max" value="${p?.max??14}" min="1" max="62" required></label><div class="full">${depts.map(d=>`<label class="check"><input type="checkbox" name="affiliation" value="${d.id}" ${(p?.affiliations||[dept]).includes(d.id)?'checked':''}>${esc(d.name)}</label>`).join('')}</div></div><div id="formerror" class="danger"></div><div class="modalactions"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">Save provider</button></div></form>`)}
function saveProvider(e,pid){e.preventDefault();let f=new FormData(e.target),p={id:pid||id(),name:f.get('name').trim(),role:f.get('role').trim(),nights:f.get('nights')==='yes',target:+f.get('target'),max:+f.get('max'),affiliations:f.getAll('affiliation')};if(!p.name||!p.affiliations.length||p.target>p.max){$('#formerror').textContent='Enter a name, choose an affiliation, and keep the target at or below the maximum.';return}let old=provider(pid);if(old){let backup={...old};Object.assign(old,p);if(state.assignments.some(a=>a.provider===pid&&state.periods[a.dept+':'+a.date.slice(0,7)]?.status==='Published'&&violations(a).length)){Object.assign(old,backup);$('#formerror').textContent='This change would conflict with a published schedule. Reopen the affected schedule first.';return}Object.assign(old,backup)}checkpoint();if(old)Object.assign(old,p);else state.providers.push(p);closeModal();commit('Saved provider · '+p.name);toast('Provider saved')}
function requestsPage(){return title('Time off, without the back-and-forth.','Review availability before it becomes a scheduling conflict.',`<button class="primary" onclick="requestDialog()">+ New request</button>`)+`<div class="tablewrap"><table><thead><tr><th>Provider</th><th>Dates</th><th>Reason</th><th>Status</th><th>Review</th></tr></thead><tbody>${state.requests.map(r=>`<tr><td><strong>${esc(provider(r.provider)?.name)}</strong></td><td>${r.start} → ${r.end}</td><td>${esc(r.reason)}</td><td><span class="pill ${r.status==='Approved'?'green':''}">${r.status}</span></td><td>${r.status==='Pending'?`<button onclick="reviewRequest('${r.id}','Approved')">Approve</button> <button onclick="reviewRequest('${r.id}','Declined')">Decline</button>`:`<button onclick="reviewRequest('${r.id}','Pending')">Reopen</button>`}</td></tr>`).join('')||'<tr><td colspan="5">No requests yet.</td></tr>'}</tbody></table></div><div class="panel" style="margin-top:20px"><h3>Availability is global.</h3><p>Approved PTO blocks overlapping shifts in every department. If an approval conflicts with existing assignments, resolve those assignments first.</p></div>`}
function requestDialog(){modal(`<h2>A little time away.</h2><p>Submit time off for scheduler review.</p><form onsubmit="saveRequest(event)"><label>Provider<select name="provider">${state.providers.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><div class="formgrid"><label>First day<input name="start" type="date" value="${iso(cursor)}" required></label><label>Last day<input name="end" type="date" value="${iso(cursor)}" required></label></div><label>Reason (optional)<input name="reason" maxlength="160"></label><div id="formerror" class="danger"></div><div class="modalactions"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">Submit request</button></div></form>`)}
function saveRequest(e){e.preventDefault();let f=new FormData(e.target),r=Object.fromEntries(f);if(r.end<r.start){$('#formerror').textContent='End date must be on or after the first day.';return}checkpoint();state.requests.push({...r,id:id(),status:'Pending'});closeModal();commit('Requested PTO · '+provider(r.provider).name+' · '+r.start);toast('Request submitted')}
function reviewRequest(rid,status){let r=state.requests.find(x=>x.id===rid);if(status==='Approved'){let start=date(r.start).getTime(),end=date(plus(r.end,1)).getTime();let conflicts=state.assignments.filter(a=>{let [s,e]=interval(a);return a.provider===r.provider&&s<end&&e>start});if(conflicts.length){toast('Approval blocked: '+conflicts.length+' assignments overlap this PTO. Move or remove them first.');return}}if(r.status==='Approved'&&status!=='Approved'&&state.assignments.some(a=>a.provider===r.provider&&state.periods[a.dept+':'+a.date.slice(0,7)]?.status==='Published')){/* Removing a block cannot invalidate assignments. */}checkpoint();r.status=status;commit(status+' PTO · '+provider(r.provider).name);toast('Request '+status.toLowerCase())}
function rulesPage(){return title('The rules behind the balance.','Clear guardrails. Consistent decisions. No mystery math.')+`<div class="notice good" style="margin-bottom:18px">Shift hours and required coverage are now configured in <a href="#" onclick="navigate('Shift types');return false">Shift types</a>.</div><form onsubmit="saveRules(event)" class="panel"><div class="panelhead"><div><h3>Scheduling guardrails</h3><p>Applies across this pilot workspace. Provider-specific maximums are managed in Providers.</p></div><span class="pill green">Hard constraints</span></div>${[['rest','Minimum rest between shifts','Hours off between any two assignments, across organizations.',0,72],['consecutive','Maximum consecutive workdays','Counts consecutive dates worked across all departments.',1,14],].map(([key,name,desc,min,max])=>`<div class="rule"><div><strong>${name}</strong><p>${desc}</p></div><input aria-label="${name}" type="number" name="${key}" value="${state.rules[key]}" min="${min}" max="${max}" required></div>`).join('')}<div class="rule"><div><strong>No overlapping assignments</strong><p>A provider can only be in one place at a time.</p></div><span class="pill green">Always enforced</span></div><div class="rule"><div><strong>Approved PTO & department affiliation</strong><p>Eligibility and availability are checked on every assignment.</p></div><span class="pill green">Always enforced</span></div><div style="margin-top:20px;text-align:right"><button class="primary">Save rules</button></div></form><div class="below"><div class="panel"><h3>Soft goals</h3><p>The generator prioritizes providers with the lowest workload relative to their monthly target, then balances night and weekend counts. Existing assignments stay in place.</p></div><div class="panel"><h3>Exceptions need their own workflow.</h3><p>This pilot blocks hard-rule violations. Approval-based rule exceptions, affiliation-specific contracts, holidays, and credential expiration are not yet implemented.</p></div></div>`}
function saveRules(e){e.preventDefault();let next=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,+v])),old=state.rules;state.rules=next;let bad=state.assignments.some(a=>state.periods[a.dept+':'+a.date.slice(0,7)]?.status==='Published'&&violations(a).length);state.rules=old;if(bad){toast('Reopen published schedules before changing rules that affect them.');return}checkpoint();state.rules=next;commit('Updated workspace scheduling rules');toast('Rules saved · Draft conflicts updated')}
function reportsPage(){let rows=state.providers.map(p=>{let a=state.assignments.filter(a=>a.provider===p.id&&a.date.startsWith(monthKey()));return {p,total:a.length,hours:a.reduce((n,x)=>n+shiftHours(x.shift),0),night:a.filter(a=>shiftType(a.shift)?.night).length,weekend:a.filter(a=>[0,6].includes(date(a.date).getDay())).length}});return title('A fairer picture.','Monthly workload across every affiliation. '+cursor.toLocaleString('en-US',{month:'long',year:'numeric'}),'<button onclick="exportCSV()">↗ Export assignments</button>')+`<div class="toolbar">${deptSelect()}<div><button onclick="changePeriod(-1)">‹ Previous</button> <button onclick="changePeriod(1)">Next ›</button></div></div>`+stats()+`<div class="tablewrap"><table><thead><tr><th>Provider</th><th>Total shifts</th><th>Nights</th><th>Weekend shifts</th><th>Hours</th><th>Target progress</th></tr></thead><tbody>${rows.map(({p,total,night,weekend,hours})=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${total} / ${p.max} max</td><td>${night}</td><td>${weekend}</td><td>${hours}</td><td><span class="progress"><i style="width:${Math.min(100,total/Math.max(1,p.target)*100)}%"></i></span> ${total}/${p.target}</td></tr>`).join('')}</tbody></table></div><div class="below"><div class="panel"><h3>Coverage gaps · ${coverageMissing().length}</h3><p>${coverageMissing().slice(0,12).map(g=>g.date+' · '+g.shift).join('<br>')||'Every required shift is covered.'}${coverageMissing().length>12?'<br>… and more':''}</p></div><div class="panel"><h3>Rule validation · ${validateAll().length}</h3><p>${validateAll().map(v=>`${v.a.date} · ${esc(provider(v.a.provider).name)} · ${esc(v.error)}`).join('<br>')||'No configured hard-rule conflicts found.'}</p></div></div>`}
function activityPage(){return title('Every change has a story.','Assignment changes, approvals, and published schedules in one place.',`<button onclick="undo()" ${!history.length?'disabled':''}>↶ Undo last change</button>`)+`<div class="panel">${state.audit.slice(0,80).map(a=>`<div class="audit"><span class="initials">JL</span><div>${esc(a.text)}<small>${new Date(a.time).toLocaleString()} · Local workspace</small></div></div>`).join('')||'<div class="empty">Your workspace activity will appear here.</div>'}</div>`}
function undo(){if(!history.length)return;state=migrate(JSON.parse(history.pop()));audit('Undid last change');persist();render();toast('Last change undone')}
function settingsPage(){return title('Your scheduling home.','A calm workspace for complicated schedules.')+`<div class="below"><div class="panel"><h3>Workspace</h3><p>Vanderbilt Midwives · Inpatient OB</p><table><tr><td>Scheduling format</td><td>Configurable shift types · 24/7</td></tr><tr><td>Organizations</td><td>Jones Team<br>Boehm Team</td></tr><tr><td>Current role</td><td>Administrator pilot</td></tr><tr><td>Call shifts</td><td>Outside V1 scope</td></tr></table></div><div class="panel"><h3>Your data, within reach.</h3><p>This interactive pilot saves automatically in this browser. Download a JSON backup to transfer or preserve your workspace.</p><button onclick="backup()">Download backup</button> <button onclick="$('#importFile').click()">Restore backup</button><input type="file" accept="application/json" id="importFile" hidden onchange="restore(event)"><p>Restoring replaces this browser’s current workspace.</p><button class="danger" onclick="resetDialog()">Reset sample workspace</button></div></div><div class="panel" style="margin-top:20px"><h3>What this pilot includes</h3><p>Interactive calendar, drag-and-drop assignments and provider cards, deterministic schedule generation, global conflicts, provider editing, PTO review, configurable rules, workload reporting, publish locks, undo, CSV exports, and backups.</p><h3 style="margin-top:20px">Before a real clinical rollout</h3><p>Shared server storage, authenticated user roles, organization-level data permissions, secure audit retention, notifications, shift swaps, credential validation, affiliation-specific rules, and operational reliability testing still need implementation. Use sample data here; this is not a production clinical scheduling system.</p></div>`}
function download(text,name,type){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function csvCell(s){let v=String(s??'');if(/^[=+@\-]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'}function exportCSV(){let rows=[['Date','Shift','Department','Organization','Provider','Start','End','Notes'],...(view==='Schedule'?displayDepartments().flatMap(d=>relevant(d.id)):relevant()).sort((a,b)=>a.date.localeCompare(b.date)||a.shift.localeCompare(b.shift)).map(a=>[a.date,shiftName(a.shift),deptName(a.dept),depts.find(d=>d.id===a.dept).org,provider(a.provider)?.name,shiftType(a.shift).start,(minutes(shiftType(a.shift).end)<=minutes(shiftType(a.shift).start)?plus(a.date,1):a.date)+' '+shiftType(a.shift).end,a.note||''])];download(rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'CountSchedula-'+monthKey()+'.csv','text/csv')}
function backup(){download(JSON.stringify(state,null,2),'CountSchedula-backup.json','application/json')}
async function restore(e){try{let data=JSON.parse(await e.target.files[0].text());if(!Array.isArray(data.providers)||!Array.isArray(data.assignments)||!Array.isArray(data.requests)||!Array.isArray(data.audit)||!data.periods||!data.rules)throw Error();data=migrate(data);validateShiftTypes(data.shiftTypes);let ids=new Set();for(let p of data.providers){if(typeof p.id!=='string'||ids.has(p.id)||typeof p.name!=='string'||typeof p.role!=='string'||!Array.isArray(p.affiliations)||p.affiliations.some(d=>!depts.some(x=>x.id===d))||!Number.isFinite(p.max)||!Number.isFinite(p.target)||p.max<1||p.target<0||p.target>p.max)throw Error();ids.add(p.id)}for(let a of data.assignments){if(!ids.has(a.provider)||!data.shiftTypes.some(t=>t.id===a.shift)||!depts.some(d=>d.id===a.dept)||!/^\d{4}-\d{2}-\d{2}$/.test(a.date))throw Error()}for(let key of ['rest','consecutive'])if(!Number.isFinite(data.rules[key])||data.rules[key]<0)throw Error();checkpoint();state=data;commit('Restored workspace backup');toast('Backup restored')}catch{toast('Could not restore: the file is not a valid CountSchedula backup.')}}
function resetDialog(){modal(`<h2>Start fresh?</h2><p>This replaces all local providers, requests, and schedules with sample data. Download a backup first if you want to keep your work.</p><div class="modalactions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="checkpoint();state=migrate(seed());generate(true);closeModal();render();toast('Sample workspace reset')">Reset workspace</button></div>`)}
function help(){modal(`<h2>A little scheduling help.</h2><p><strong>Move an assignment:</strong> drag a shift card to a new date, or onto an open shift slot to change its shift.<br><br><strong>Add a shift:</strong> drag a provider from the team tray to the calendar, click an open slot, or use a date’s + button.<br><br><strong>Keep it safe:</strong> blocked moves explain the conflicting rule. Published schedules must be reopened before editing.<br><br><strong>Keyboard:</strong> Tab to a shift and press Enter to edit its date, provider, or shift. Changes can be undone in Activity.<br><br>All sample shift times use the same local time zone. Cross-time-zone scheduling is not implemented.</p><div class="modalactions"><button class="primary" onclick="closeModal()">Got it</button></div>`)}
function validateShiftTypes(types){if(!Array.isArray(types)||!types.length)throw Error('At least one shift type is required');let ids=new Set(),names=new Set();for(let t of types){if(!/^[a-z0-9-]+$/.test(t.id)||ids.has(t.id)||typeof t.name!=='string'||!t.name.trim()||t.name.length>40||names.has(t.name.trim().toLowerCase())||!/^([01]\d|2[0-3]):[0-5]\d$/.test(t.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(t.end)||t.start===t.end||!/^#[a-f0-9]{6}$/i.test(t.color)||!Number.isInteger(t.coverage)||t.coverage<0||t.coverage>10||typeof t.active!=='boolean'||typeof t.night!=='boolean')throw Error('Check shift names, hours, color, and required coverage (0–10). Names must be unique and start/end times must differ.');ids.add(t.id);names.add(t.name.trim().toLowerCase())}if(!types.some(t=>t.active))throw Error('Keep at least one shift type active')}
function shiftTypesPage(){return title('Every kind of shift. One schedule.','Configure the hours, color, and daily coverage for each shift type.',`<button class="primary" onclick="shiftTypeDialog()">+ Add shift type</button>`)+`<div class="notice good" style="margin-bottom:18px">Day and Night retain their existing assignments. The four additional sample types start with 0 required providers per day—available for manual assignments. Raise coverage to include them in open shifts and automatic generation.</div><div class="tablewrap"><table><thead><tr><th>Shift type</th><th>Hours</th><th>Duration</th><th>Required / day</th><th>Night category</th><th>Status</th><th></th></tr></thead><tbody>${state.shiftTypes.map(t=>`<tr><td><span class="dot" style="background:${t.color}"></span><strong>${esc(t.name)}</strong></td><td>${shiftRange(t)}${minutes(t.end)<minutes(t.start)?' <small class="muted">(+1 day)</small>':''}</td><td>${shiftHours(t.id)}h</td><td>${t.coverage}${t.coverage===0?' · Optional':''}</td><td>${t.night?'Yes':'No'}</td><td><span class="pill ${t.active?'green':''}">${t.active?'Active':'Inactive'}</span></td><td><button onclick="shiftTypeDialog('${t.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div><div class="below"><div class="panel"><h3>Coverage drives the calendar.</h3><p>Required providers are counted per day, for each department. A value of 0 makes a shift optional. Active types appear in assignment editors and the calendar legend.</p></div><div class="panel"><h3>Hours drive conflict checks.</h3><p>Overnight shifts end the following day. Overlap, rest, PTO, exports, and reported hours use each type’s configured times. Night-category shifts follow provider night availability.</p></div></div>`}
function shiftTypeDialog(tid){let t=shiftType(tid);modal(`<h2>${t?'Edit shift type':'Add a shift type'}</h2><p>Changes apply across this workspace. Required coverage applies every day to both departments.</p><form onsubmit="saveShiftType(event,'${tid||''}')"><div class="formgrid"><label class="full">Name<input name="name" required maxlength="40" value="${esc(t?.name||'')}"></label><label>Start time<input type="time" name="start" required value="${t?.start||'07:00'}"></label><label>End time<input type="time" name="end" required value="${t?.end||'19:00'}"></label><label>Required providers per day<input type="number" name="coverage" min="0" max="10" step="1" required value="${t?.coverage??0}"></label><label>Calendar color<input type="color" name="color" value="${t?.color||'#6b9b69'}"></label><label class="check"><input type="checkbox" name="night" ${t?.night?'checked':''}>Night category</label><label class="check"><input type="checkbox" name="active" ${!t||t.active?'checked':''}>Active</label></div><p>End times earlier than start times finish the next day. Deactivate a type to stop new assignments while retaining history.</p><div id="formerror" class="danger" role="alert"></div><div class="modalactions"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">Save shift type</button></div></form>`)}
function saveShiftType(e,tid){e.preventDefault();let f=new FormData(e.target),t={id:tid||'shift-'+id().replaceAll('-',''),name:f.get('name').trim(),start:f.get('start'),end:f.get('end'),color:f.get('color'),coverage:+f.get('coverage'),night:f.has('night'),active:f.has('active')},old=shiftType(tid),next=state.shiftTypes.map(x=>x.id===tid?t:x);if(!old)next.push(t);try{validateShiftTypes(next)}catch(err){$('#formerror').textContent=err.message;return}let published=Object.values(state.periods).some(p=>p.status==='Published'),referenced=state.assignments.some(a=>a.shift===tid&&state.periods[a.dept+':'+a.date.slice(0,7)]?.status==='Published');if((published&&((old?.active?old.coverage:0)!==(t.active?t.coverage:0)))||(referenced&&(t.start!==old.start||t.end!==old.end||t.night!==old.night))){$('#formerror').textContent='Reopen affected published schedules before changing required coverage or assigned shift hours/category.';return}checkpoint();state.shiftTypes=next;closeModal();commit('Saved shift type · '+t.name);toast('Shift type saved · Calendar and coverage updated')}

const organizations=[...new Set(depts.map(d=>d.org))].map((name,i)=>({id:depts.find(d=>d.org===name).id,name,short:name,color:['#377862','#527ca8','#a0744a'][i%3]}));
function organizationFor(department){return organizations.find(o=>o.name===depts.find(d=>d.id===department)?.org)||organizations[0]}
function displayOrganizations(){return organizations.filter(o=>selectedOrgs.includes(o.id))}
function displayDepartments(){return depts.filter(d=>displayOrganizations().some(o=>o.name===d.org))}
function isPublished(department,day){return state.periods[department+':'+day.slice(0,7)]?.status==='Published'}
function organizationPicker(){return `<details class="org-picker"><summary aria-label="Display organizations">${selectedOrgs.length===1?esc(displayOrganizations()[0].name):selectedOrgs.length+' organizations'} <span>⌄</span></summary><div class="org-picker-menu"><strong>Display organizations</strong>${organizations.map(o=>`<label class="check"><input type="checkbox" value="${o.id}" ${selectedOrgs.includes(o.id)?'checked':''} onchange="toggleOrganization(this.value,this.checked,this)"><i class="dot" style="background:${o.color}"></i>${esc(o.name)}</label>`).join('')}<button onclick="selectedOrgs=organizations.map(o=>o.id);render()">Select all</button><p>Choose one or more organizations.</p></div></details>`}
function toggleOrganization(id,checked,input){if(!checked&&selectedOrgs.length===1){input.checked=true;toast('Keep at least one organization selected.');return}selectedOrgs=checked?[...new Set([...selectedOrgs,id])]:selectedOrgs.filter(x=>x!==id);render();let picker=$('.org-picker');if(picker)picker.open=true}
function updateAssignmentProviders(department){let select=$('#modal select[name="provider"]'),old=select.value;select.innerHTML=state.providers.filter(p=>p.affiliations.includes(department)).map(p=>`<option value="${p.id}" ${p.id===old?'selected':''}>${esc(p.name)}</option>`).join('');let day=$('#modal input[name="date"]').value;$('#modal button.primary').disabled=isPublished(department,day)}
document.addEventListener('click',e=>{let picker=$('.org-picker');if(picker&&e.target.isConnected&&!picker.contains(e.target))picker.open=false});
if(!localStorage.getItem(KEY)){generate(true);history=[]}else render();
